    public async Task SeedAsync(CancellationToken cancellationToken = default)
    {
        var databaseType = configuration.GetSection("AppSettings:DatabaseType").Get<string>();
        if (string.IsNullOrWhiteSpace(databaseType) ||
            databaseType.Equals("inMemory", StringComparison.OrdinalIgnoreCase))
        {
            return;
        }

        if (!configuration.GetValue("AskAiCatalogSeed:Enabled", true))
        {
            logger.LogInformation("Ask AI catalog seed is disabled (AskAiCatalogSeed:Enabled=false).");
            return;
        }

        await using var connection = await connectionFactory.CreateWriteConnectionAsync(cancellationToken);
        if (!await TableExistsAsync(connection, databaseType, "PROJECT_QA_CATALOGS").ConfigureAwait(false))
        {
            logger.LogDebug("PROJECT_QA_CATALOGS not found; skipping Ask AI catalog seed.");
            return;
        }

        var projectKeys = configuration.GetSection("AskAiCatalogSeed:ProjectKeys").Get<string[]>() ?? Array.Empty<string>();
        var projects = (await LoadActiveProjectsAsync(connection, databaseType, projectKeys).ConfigureAwait(false)).ToList();
        if (projects.Count == 0)
        {
            logger.LogInformation("No active projects matched Ask AI catalog seed filters.");
            return;
        }

        var seeded = 0;
        foreach (var project in projects)
        {
            try
            {
                if (await UpsertCatalogAsync(connection, databaseType, project, cancellationToken).ConfigureAwait(false))
                    seeded++;
            }
            catch (Exception ex)
            {
                logger.LogWarning(ex, "Ask AI catalog seed failed for project {ProjectKey}", project.Key);
            }
        }

        logger.LogInformation("Ask AI catalog seed completed for {SeededCount}/{ProjectCount} project(s).", seeded, projects.Count);
    }

    private async Task<bool> UpsertCatalogAsync(
        System.Data.Common.DbConnection connection,
        string databaseType,
        ProjectRow project,
        CancellationToken cancellationToken)
    {
        var modules = (await LoadProjectModulesAsync(connection, databaseType, project.Id).ConfigureAwait(false)).ToList();
        var activeContext = await LoadActiveProjectContextAsync(connection, databaseType, project.Id).ConfigureAwait(false);
        var moduleContexts = (await LoadActiveModuleContextsAsync(connection, databaseType, project.Id).ConfigureAwait(false))
            .ToDictionary(m => m.ModuleName, StringComparer.OrdinalIgnoreCase);

        var hashBuilder = new StringBuilder();
        Guid? projectContextId = activeContext?.Id;
        if (activeContext != null)
        {
            hashBuilder.Append(activeContext.Id)
                .Append('|').Append(activeContext.Version)
                .Append('|').Append(NormalizeDate(activeContext.UpdatedDate));
        }

        var moduleEntries = new List<CatalogModuleEntry>();
        foreach (var module in modules)
        {
            hashBuilder.Append('|').Append(module.ModuleName)
                .Append('|').Append(NormalizeDate(module.UpdatedDate));

            moduleContexts.TryGetValue(module.ModuleName, out var moduleContext);
            if (moduleContext != null)
            {
                hashBuilder.Append('|').Append(moduleContext.Version)
                    .Append('|').Append(NormalizeDate(moduleContext.UpdatedDate));
            }

            var tables = ExtractTables(module.Dbml);
            var concepts = ExtractConcepts(moduleContext?.Payload);
            moduleEntries.Add(new CatalogModuleEntry
            {
                ModuleId = moduleContext?.ModuleId ?? module.ModuleName,
                ModuleName = module.ModuleName,
                Aliases = BuildAliases(module.ModuleName),
                Concepts = concepts,
                Tables = tables,
                HasContext = !string.IsNullOrWhiteSpace(moduleContext?.Payload),
                HasDbml = !string.IsNullOrWhiteSpace(module.Dbml)
            });
        }

        var payload = new CatalogPayload
        {
            Project = new CatalogProjectEntry
            {
                Name = project.Name ?? project.Key,
                Aliases = BuildAliases(project.Name ?? project.Key)
            },
            Modules = moduleEntries
        };

        var payloadJson = JsonSerializer.Serialize(payload, JsonOptions);
        var sourceHash = ComputeHash(hashBuilder.ToString());
        var now = DateTime.UtcNow;

        var existing = await connection.QueryFirstOrDefaultAsync<Guid?>(
            $"SELECT {Quote("PROJECT_ID", databaseType)} FROM {Quote("PROJECT_QA_CATALOGS", databaseType)} WHERE {Quote("PROJECT_ID", databaseType)} = @ProjectId",
            new { ProjectId = project.Id }).ConfigureAwait(false);

        if (existing.HasValue)
        {
            await connection.ExecuteAsync(
                BuildUpdateSql(databaseType),
                new
                {
                    ProjectId = project.Id,
                    SourceHash = sourceHash,
                    Payload = payloadJson,
                    ProjectContextId = projectContextId,
                    UpdatedDate = now
                }).ConfigureAwait(false);
        }
        else
        {
            await connection.ExecuteAsync(
                BuildInsertSql(databaseType),
                new
                {
                    ProjectId = project.Id,
                    SourceHash = sourceHash,
                    Payload = payloadJson,
                    ProjectContextId = projectContextId,
                    CreatedDate = now,
                    UpdatedDate = now
                }).ConfigureAwait(false);
        }

        logger.LogInformation(
            "Seeded Ask AI catalog for {ProjectKey}: {ModuleCount} module(s), hash={HashPrefix}…",
            project.Key,
            moduleEntries.Count,
            sourceHash.Length >= 12 ? sourceHash[..12] : sourceHash);

        return true;
    }

    private static async Task<IEnumerable<ProjectRow>> LoadActiveProjectsAsync(
        System.Data.Common.DbConnection connection,
        string databaseType,
        string[] projectKeys)
    {
        var projectTable = Quote("PROJECTS", databaseType);
        var sql = $"""
            SELECT {Quote("ID", databaseType)} AS Id,
                   {Quote("KEY", databaseType)} AS {Quote("Key", databaseType)},
                   {Quote("NAME", databaseType)} AS Name
            FROM {projectTable}
            WHERE {Quote("IS_ACTIVE", databaseType)} = @IsActive
            ORDER BY {Quote("KEY", databaseType)}
            """;

        var rows = await connection.QueryAsync<ProjectRow>(sql, new { IsActive = true }).ConfigureAwait(false);
        if (projectKeys.Length == 0)
            return rows;

        var allowed = new HashSet<string>(projectKeys, StringComparer.OrdinalIgnoreCase);
        return rows.Where(p => allowed.Contains(p.Key));
    }

    private static async Task<IEnumerable<ModuleRow>> LoadProjectModulesAsync(
        System.Data.Common.DbConnection connection,
        string databaseType,
        Guid projectId)
