            SELECT PM.{Quote("MODULE_NAME", databaseType)} AS ModuleName,
                   R.{Quote("DBML", databaseType)} AS Dbml,
                   PM.{Quote("UPDATED_DATE", databaseType)} AS UpdatedDate
            FROM {Quote("PROJECT_MODULES", databaseType)} PM
            INNER JOIN {Quote("PROJECT_MODULE_DBML_VERSIONS", databaseType)} R
                ON R.{Quote("ID", databaseType)} = PM.{Quote("CURRENT_DBML_VERSION_ID", databaseType)}
            WHERE PM.{Quote("PROJECT_ID", databaseType)} = @ProjectId
            ORDER BY PM.{Quote("MODULE_NAME", databaseType)}
            """;
        return await connection.QueryAsync<ModuleRow>(sql, new { ProjectId = projectId }).ConfigureAwait(false);
    }

