    private static async Task<bool> TableExistsAsync(
        System.Data.Common.DbConnection connection,
        string databaseType,
        string tableName)
    {
        var sql = databaseType.ToLowerInvariant() switch
        {
            "mssql" => """
                SELECT CASE WHEN OBJECT_ID(N'dbo.' + @TableName, N'U') IS NULL THEN 0 ELSE 1 END
                """,
            "postgresql" => """
                SELECT CASE WHEN to_regclass('public.' || lower(@TableName)) IS NULL THEN 0 ELSE 1 END
                """,
            "mysql" => """
                SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END
                FROM information_schema.tables
                WHERE table_schema = DATABASE() AND table_name = @TableName
                """,
            _ => null
        };

        if (sql is null)
            return false;

        var exists = await connection.ExecuteScalarAsync<int>(sql, new { TableName = tableName }).ConfigureAwait(false);
        return exists > 0;
    }

