    private static string ComputeHash(string input)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(input));
        return Convert.ToHexString(bytes).ToLowerInvariant();
    }

    private static string? NormalizeDate(DateTime? value) => value?.ToUniversalTime().ToString("O");

    private static List<string> BuildAliases(string? name)
    {
        if (string.IsNullOrWhiteSpace(name))
            return new List<string>();

        var aliases = new List<string> { name.Trim() };
        var withoutModule = Regex.Replace(name.Trim(), "Module$", string.Empty, RegexOptions.IgnoreCase).Trim();
        if (!string.Equals(withoutModule, name.Trim(), StringComparison.OrdinalIgnoreCase) && withoutModule.Length >= 2)
            aliases.Add(withoutModule);
        return aliases.Distinct(StringComparer.OrdinalIgnoreCase).ToList();
    }

    private static List<string> ExtractTables(string? dbml)
    {
        if (string.IsNullOrWhiteSpace(dbml))
            return new List<string>();

        return Regex.Matches(dbml, @"Table\s+""([^""]+)""", RegexOptions.IgnoreCase)
            .Select(m => m.Groups[1].Value)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(48)
            .ToList();
    }

    private static List<string> ExtractConcepts(string? modulePayloadJson)
    {
        var concepts = new List<string>();
        if (string.IsNullOrWhiteSpace(modulePayloadJson))
            return concepts;

        try
        {
            using var doc = JsonDocument.Parse(modulePayloadJson);
            if (doc.RootElement.TryGetProperty("domainConcepts", out var arr))
            {
                foreach (var item in arr.EnumerateArray())
                {
                    if (item.TryGetProperty("name", out var name) && !string.IsNullOrWhiteSpace(name.GetString()))
                        concepts.Add(name.GetString()!);
                }
            }
        }
        catch
        {
        }

        return concepts.Distinct(StringComparer.OrdinalIgnoreCase).Take(24).ToList();
    }

